(function(){
  var root=document.querySelector('[data-manga-app]');if(!root)return;
  var base='https://firebasestorage.googleapis.com/v0/b/poketquest-3a73d.firebasestorage.app/o/japaneseLearning%2Fmanga%2Fn5%2Fkawaii-character-culture%2Fv1%2F';
  var images={ja:base+'ja.jpg?alt=media',en:base+'en.jpg?alt=media'},stateKey='japaneseLearning.manga.n5_manga.nextQuestion.v1';
  var questions=[
    {q:'What happened to the mouthless charm when the person smiled?',c:['It smiled too','It fell asleep','It began to talk','It turned blue'],a:0,e:'When the person smiled, the charm smiled with them.'},
    {q:"What is the manga's final message about kawaii characters?",c:['They are only for children','They can share feelings without words','They must always look happy','They replace friendship'],a:1,e:"Kawaii characters can connect people's feelings even without words."}
  ];
  var reader=root.querySelector('[data-reader]'),quiz=root.querySelector('[data-quiz]'),complete=root.querySelector('[data-complete]'),image=root.querySelector('[data-manga-image]'),frame=root.querySelector('.manga-frame'),status=root.querySelector('[data-image-status]'),progress=root.querySelector('[data-progress-bar]'),index=Math.min(questions.length-1,Number(localStorage.getItem(stateKey))||0),locked=false;
  function save(value){localStorage.setItem(stateKey,String(value));window.dispatchEvent(new CustomEvent('manga-progress',{detail:{courseId:'n5_manga',completedSteps:value,totalSteps:questions.length,progressPercent:value*100/questions.length}}));}
  function loadImage(lang){frame.classList.remove('loaded');status.textContent='Loading manga…';image.onload=function(){frame.classList.add('loaded');};image.onerror=function(){var fallback='https://shimizu510.github.io/japan-unfolded/assets/'+(lang==='ja'?'kawaii-character-culture-n5-manga.png':'kawaii-character-culture-n5-manga-en.png');if(image.src!==fallback){image.src=fallback;return;}status.textContent='The manga could not be loaded. Please try again.';};image.src=images[lang];root.querySelectorAll('[data-manga-language]').forEach(function(button){var active=button.dataset.mangaLanguage===lang;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active?'true':'false');});}
  function showReader(){reader.hidden=false;quiz.hidden=true;complete.hidden=true;progress.style.width=(index?50:33)+'%';reader.scrollIntoView({behavior:'smooth',block:'start'});}
  function showQuiz(){reader.hidden=true;quiz.hidden=false;complete.hidden=true;renderQuestion();quiz.scrollIntoView({behavior:'smooth',block:'start'});}
  function renderQuestion(){locked=false;var item=questions[index];progress.style.width=(60+index*22)+'%';root.querySelector('[data-question-count]').textContent='Question '+(index+1)+' of '+questions.length;root.querySelector('[data-question-number]').textContent=String(index+1).padStart(2,'0');root.querySelector('[data-question]').textContent=item.q;var feedback=root.querySelector('[data-feedback]');feedback.textContent='';feedback.className='quiz-feedback';var choices=root.querySelector('[data-choices]');choices.innerHTML='';item.c.forEach(function(label,i){var button=document.createElement('button');button.type='button';button.className='quiz-choice';button.textContent=label;button.onclick=function(){choose(i);};choices.appendChild(button);});}
  function choose(selected){if(locked)return;locked=true;var item=questions[index],buttons=root.querySelectorAll('.quiz-choice'),correct=selected===item.a;buttons.forEach(function(button,i){button.disabled=true;if(i===item.a)button.classList.add('correct');});var feedback=root.querySelector('[data-feedback]');feedback.textContent=(correct?'Correct! ':'Not quite. ')+item.e;feedback.classList.add(correct?'good':'try');setTimeout(function(){if(index+1<questions.length){index++;save(index);renderQuestion();return;}save(questions.length);quiz.hidden=true;complete.hidden=false;progress.style.width='100%';complete.scrollIntoView({behavior:'smooth',block:'start'});},1150);}
  root.querySelectorAll('[data-manga-language]').forEach(function(button){button.onclick=function(){loadImage(button.dataset.mangaLanguage);};});root.querySelector('[data-start-questions]').onclick=showQuiz;root.querySelector('[data-reread]').onclick=showReader;root.querySelector('[data-read-again]').onclick=function(){index=0;save(0);showReader();};loadImage('ja');
  if(new URLSearchParams(location.search).get('resume')==='1'&&Number(localStorage.getItem(stateKey))>0)showQuiz();
})();
